from collections import defaultdict

from neo4j import GraphDatabase

# Update these with your Neo4j instance details
NEO4J_URI = "bolt://localhost:31005"
NEO4J_USER = "neo4j"
NEO4J_PASSWORD = "<password>"


class Neo4jConnection:
    def __init__(self, uri, user, password):
        self.driver = GraphDatabase.driver(uri, auth=(user, password))

    def close(self):
        self.driver.close()

    def execute_query(self, query, parameters=None):
        with self.driver.session() as session:
            result = session.run(query, parameters or {})
            return [record.data() for record in result]


if __name__ == "__main__":
    conn = Neo4jConnection(NEO4J_URI, NEO4J_USER, NEO4J_PASSWORD)
    try:
        # Example query: get all nodes
        query = """
        MATCH (head:Chunk)
        WHERE head.chunkIdx = 0 AND head.uuid = '9ade3bb5-451a-4a0e-854d-a8c308bc0bc6'
        WITH head
        ORDER BY id(head) ASC
        LIMIT 1

        MATCH path = (head)-[:NEXT_CHUNK*0..]->(c:Chunk)
        RETURN nodes(path) AS chunks
        ORDER BY length(path) DESC
        LIMIT 1
        """
        results = conn.execute_query(query)
        print("Query Results:")
        # Segregate and concatenate text by (start_time, end_time)
        grouped = defaultdict(list)
        for row in results:
            # Each row should have a 'chunks' key with a list of nodes
            chunks = row.get("chunks", [])
            for chunk in chunks:
                start = chunk.get("start_time")
                end = chunk.get("end_time")
                text = chunk.get("text", "")
                if start is not None and end is not None:
                    grouped[(start, end)].append(text)
        for (start, end), texts in grouped.items():
            print(f"start_time: {start}, end_time: {end}")
            print("Concatenated text:", " ".join(texts))
    finally:
        conn.close()
